def max_occurrences(lst):
    """Return the item with maximum frequency in a given list."""
    # Create a dictionary to store the frequency of each item
    freq = {}
    for item in lst:
        if item in freq:
            freq[item] += 1
        else:
            freq[item] = 1
    # Find the item with maximum frequency
    max_freq = max(freq.values())
    for item, count in freq.items():
        if count == max_freq:
            return item, max_freq

def reverse_vowels(s):
    vowels = "aeiouAEIOU"
    s = list(s)
    i, j = 0, len(s) - 1
    while i < j:
        if s[i] not in vowels:
            i += 1
        elif s[j] not in vowels:
            j -= 1
        else:
            s[i], s[j] = s[j], s[i]
            i += 1
            j -= 1
    return "".join(s)

